package com.zjnu.lab.controller;
import com.zjnu.lab.common.*; import com.zjnu.lab.mapper.*; import com.zjnu.lab.model.*; import com.zjnu.lab.util.SecurityUtil; import lombok.RequiredArgsConstructor; import org.springframework.transaction.annotation.Isolation; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import java.time.*; import java.util.*;
import com.zjnu.lab.service.LabScopeService;
@RestController @RequiredArgsConstructor public class ReservationController {private final ReservationMapper mapper;private final LabMapper labs;private final LabScopeService scope;
 @GetMapping("/reservations/my") public ApiResponse<?> mine(@RequestParam(required=false)String status){return ApiResponse.ok(mapper.list(SecurityUtil.userId(),status,null));}
 @GetMapping("/manage/reservations") public ApiResponse<?> all(@RequestParam(required=false)String status){return ApiResponse.ok(mapper.list(null,status,scope.scope()));}
 @GetMapping("/reservations/calendar") public ApiResponse<?> calendar(@RequestParam Long labId,@RequestParam LocalDate from,@RequestParam LocalDate to){if(to.isBefore(from)||to.isAfter(from.plusDays(62)))throw new BusinessException("日历查询范围最多为63天");Lab lab=labs.get(labId);scope.requireAccess(lab);if(lab==null)throw new BusinessException("实验室不存在");return ApiResponse.ok(mapper.calendar(labId,from,to).stream().map(r->Map.of("reserveDate",r.getReserveDate(),"startTime",r.getStartTime(),"endTime",r.getEndTime(),"status",r.getStatus())).toList());}
 @GetMapping("/reservations/recommendations") public ApiResponse<?> recommendations(@RequestParam Long labId,@RequestParam LocalDate date,@RequestParam Integer durationMinutes){Lab lab=labs.get(labId);scope.requireAccess(lab);if(lab==null||lab.getOpenStatus()!=1)throw new BusinessException("实验室当前未开放");if(durationMinutes<30||durationMinutes>480||durationMinutes%30!=0)throw new BusinessException("预约时长须为30至480分钟且为30分钟的倍数");if(date.isBefore(LocalDate.now()))throw new BusinessException("预约日期不能早于今天");LocalTime open=LocalTime.parse(lab.getOpenTime()),close=LocalTime.parse(lab.getCloseTime());List<Reservation> busy=mapper.busyPeriods(labId,date);List<Map<String,String>> slots=new ArrayList<>();for(LocalTime start=open;!start.plusMinutes(durationMinutes).isAfter(close);start=start.plusMinutes(30)){LocalTime candidateStart=start;LocalTime end=candidateStart.plusMinutes(durationMinutes);if(date.equals(LocalDate.now())&&candidateStart.isBefore(LocalTime.now()))continue;boolean conflict=busy.stream().anyMatch(r->candidateStart.isBefore(r.getEndTime())&&end.isAfter(r.getStartTime()));if(!conflict)slots.add(Map.of("startTime",candidateStart.toString(),"endTime",end.toString()));}return ApiResponse.ok(slots);}
 @PostMapping("/reservations") @Transactional public ApiResponse<?> add(@Valid @RequestBody Reservation r){Lab l=labs.get(r.getLabId());scope.requireAccess(l);if(l==null||l.getOpenStatus()!=1)throw new BusinessException("实验室当前未开放");if(r.getReserveDate().isBefore(LocalDate.now())||!r.getStartTime().isBefore(r.getEndTime()))throw new BusinessException("预约日期或时间不正确");if(r.getParticipants()>l.getCapacity())throw new BusinessException("预约人数超过实验室容量");LocalTime open=LocalTime.parse(l.getOpenTime()),close=LocalTime.parse(l.getCloseTime());if(r.getStartTime().isBefore(open)||r.getEndTime().isAfter(close))throw new BusinessException("预约时间不在开放时段内");long startOffset=Duration.between(open,r.getStartTime()).toMinutes(),endOffset=Duration.between(open,r.getEndTime()).toMinutes(),duration=Duration.between(r.getStartTime(),r.getEndTime()).toMinutes();boolean endAligned=r.getEndTime().equals(close)||endOffset%30==0;if(r.getStartTime().getSecond()!=0||r.getEndTime().getSecond()!=0||duration<30||duration%30!=0||startOffset%30!=0||!endAligned)throw new BusinessException("预约时间须按30分钟刻度选择且至少预约30分钟");if(mapper.conflict(r.getLabId(),r.getReserveDate(),r.getStartTime(),r.getEndTime(),null)>0)throw new BusinessException("该时间段已被预约");r.setApplicantId(SecurityUtil.userId());mapper.insert(r);return ApiResponse.ok(r);}
 @PutMapping("/reservations/{id}/cancel") public ApiResponse<?> cancel(@PathVariable Long id){Reservation r=mapper.get(id);if(r==null||!r.getApplicantId().equals(SecurityUtil.userId()))throw new BusinessException("无权取消该预约");LocalDateTime start=LocalDateTime.of(r.getReserveDate(),r.getStartTime());if(!List.of("PENDING","APPROVED").contains(r.getStatus())||!LocalDateTime.now().isBefore(start.minusHours(2)))throw new BusinessException("预约开始前2小时内不可取消");mapper.cancel(id);return ApiResponse.ok();}
 public record Audit(String status,String reason){}
 @PutMapping("/manage/reservations/{id}/audit") @Transactional(isolation=Isolation.READ_COMMITTED) public ApiResponse<?> audit(@PathVariable Long id,@RequestBody Audit a){Reservation r=mapper.get(id);if(r==null||!"PENDING".equals(r.getStatus()))throw new BusinessException("预约状态已变化");scope.requireAccess(r.getLabId());if(!List.of("APPROVED","REJECTED").contains(a.status()))throw new BusinessException("审核状态错误");if("REJECTED".equals(a.status())&&(a.reason()==null||a.reason().isBlank()))throw new BusinessException("拒绝时请填写原因");if("APPROVED".equals(a.status())){mapper.lockLabForApproval(r.getLabId());if(mapper.conflict(r.getLabId(),r.getReserveDate(),r.getStartTime(),r.getEndTime(),id)>0)throw new BusinessException("该时间段已被其他预约占用，无法通过");}if(mapper.audit(id,a.status(),a.reason(),SecurityUtil.userId())!=1)throw new BusinessException("预约状态已变化");return ApiResponse.ok();}
}
